        if (con.getContentType() != null) {
            try {
                charset = MediaType.parse(con.getContentType()).charset().or(StandardCharsets.UTF_8);
            } catch (IllegalArgumentException ignored) {}
        }
        return new String(out.toByteArray(), charset);
    }

